// Highway generates code for each supported target by re-including this file. The following path is relative to the package `include` directory (i.e., `./include/../src/dsumpw_highway.cpp`), which is on the include path when compiling the add-on. Note that `__FILE__` is not a reliable path for re-inclusion. As the path is resolved by searching include directories, the file name must be unique among the packages compiled into an add-on (hence, the file name includes the package name):
#undef HWY_TARGET_INCLUDE
#define HWY_TARGET_INCLUDE "../src/dsumpw_highway.cpp"
